<script setup>
import {ref,watch} from 'vue';import {language} from '../i18n';import {resolveDestinations} from '../providers/destinationResolver';import {searchNamed} from '../services/namedPlaces';import UnifiedTripMap from './UnifiedTripMap.vue';
const props=defineProps({city:String,kind:String});const emit=defineEmits(['choose']);const query=ref(''),results=ref([]),cities=ref([]),destination=ref(null),busy=ref(false),error=ref(''),active=ref(''),manual=ref(false),point=ref(null);let version=0;
watch(()=>props.city,()=>{version++;destination.value=null;results.value=[];cities.value=[];point.value=null;busy.value=false;});
async function search(city){const token=++version;busy.value=true;error.value='';try{if(city)destination.value=city;if(!destination.value){cities.value=await resolveDestinations(props.city);if(cities.value.length!==1)return;destination.value=cities.value[0];}cities.value=[];const data=await searchNamed(destination.value,query.value,props.kind);if(token===version){results.value=data;if(!data.length)error.value=language.value==='zh'?'未找到准确地点，请换名称或在地图选点。':'No matching place. Try another name or select on the map.';}}catch{if(token===version)error.value=language.value==='zh'?'地点服务暂不可用，请重试或在地图选点。':'Place service unavailable. Retry or choose on the map.';}finally{if(token===version)busy.value=false;}}
function choose(p){emit('choose',{...p,destination:destination.value});results.value=[];active.value=p.id;}
function usePoint(){choose({id:'manual-'+crypto.randomUUID(),name:query.value|| (language.value==='zh'?'用户标记位置':'User marked location'),...point.value,role:props.kind,category:props.kind==='hotel'?'HOTEL':'FOOD',source:'user-location',coordinateSystem:destination.value.countryCode==='CN'?'GCJ02':'WGS84',countryCode:destination.value.countryCode,city:destination.value.city,address:language.value==='zh'?'用户地图选点，未核实商户身份':'User map point; business identity unverified',subcategories:['FOOD'],planningEligible:true,estimatedDuration:60,minimumDuration:30});point.value=null;manual.value=false;}
</script>
<template><div class="place-picker"><div class="wish-input"><input v-model="query" :aria-label="kind==='hotel'?(language==='zh'?'搜索酒店':'Search hotels'):(language==='zh'?'搜索餐厅':'Search restaurants')" @keydown.enter.prevent="search()"/><button type="button" @click="search()" :disabled="busy||!city||query.trim().length<2">{{busy?(language==='zh'?'搜索中…':'Searching…'):(language==='zh'?'搜索':'Search')}}</button></div><p v-if="error" role="status">{{error}}</p><button v-for="c in cities" :key="c.id" type="button" @click="search(c)">{{c.displayName}} · {{c.country}} · {{c.region}}</button><article v-for="p in results" :key="p.id"><strong>{{p.name}}</strong><p>{{p.address}} · {{p.latitude.toFixed(5)}}, {{p.longitude.toFixed(5)}}</p><button type="button" @click="active=p.id">{{language==='zh'?'地图定位':'Show on map'}}</button><button type="button" @click="choose(p)">{{language==='zh'?'确认此地点':'Choose this location'}}</button></article><button v-if="destination" type="button" class="text-button" @click="manual=!manual">{{language==='zh'?'在地图上选择位置':'Select a location on the map'}}</button><UnifiedTripMap v-if="destination&&(results.length||manual)" :destination="destination" :places="results" :active="active" selecting :marking="manual" @select="active=$event" @pick="point=$event" @add="choose"/><p v-if="point">{{point.latitude.toFixed(5)}}, {{point.longitude.toFixed(5)}} <button type="button" @click="usePoint">{{language==='zh'?'确认用户标记位置（商户未核实）':'Confirm marked location (business unverified)'}}</button></p><small v-if="destination?.countryCode!=='CN'">© OpenStreetMap contributors · ODbL</small></div></template>
<style scoped>.place-picker article{border-bottom:1px solid var(--border);padding:12px 0}.place-picker p{font-size:13px}.place-picker button{margin:4px;min-height:36px}.place-picker input{min-width:0}</style>
